else if (event is AddItemToCart) {
  final updatedCartItems = List<CartItem>.from(state.cartItems)
    ..add(event.cartItem); // Assuming event.cartItem is the item to add

  // Recalculate total price
  final totalPrice = updatedCartItems.fold<double>(
    0.0,
    (previousValue, cartItem) => previousValue + (cartItem.product.price * cartItem.quantity),
  );

  // Emit the new state
  emit(state.copyWith(
    cartItems: updatedCartItems,
    totalPrice: totalPrice,
  ));
}
